    case "markdown":
      writerFormat = pandocMarkdownFormat();
      pandocTo = to;
      break;

    case "markdown_phpextra":
    case "markdown_github":
    case "markdown_mmd":
    case "markdown_strict":
      writerFormat = markdownFormat("Markdown");
      pandocTo = to;
      break;

